  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "PTC518 showed CSF concentrations 2.6-fold higher than unbound plasma in humans, directly demonstrating meaningful CNS access after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "A closely related pyrazolopyrimidine with high TPSA achieved a brain-to-plasma ratio of 0.32 in rat and was considered to have reasonable brain uptake, supporting CNS access for the query's similar heteroaromatic core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "T-3811ME entered CSF readily with a CSF/serum AUC of 13–16% in rabbits, providing direct CSF evidence of meaningful CNS penetration despite polar functionality.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A fluorinated heteroaromatic PET tracer exhibited excellent brain uptake in mouse dynamic PET imaging, supporting that the query's fluorinated aromatic/heteroaromatic ether motifs are compatible with BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Decursin showed brain-to-plasma ratios greater than 1.5 in rats after oral dosing, providing direct in vivo evidence that fused lipophilic heterocycles can achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show positive CNS access via human CSF, rat brain uptake, rabbit CSF, and PET imaging, including a structurally related pyrazolopyrimidine with reasonable brain penetration. The query is therefore predicted to have meaningful CNS access.",
  "evidence_gaps": [
    "No direct CSF or brain pharmacokinetic measurement for the exact query molecule.",
    "Efflux transporter (P-gp/BCRP) status for the query has not been experimentally assessed.",
    "The transfer scores are high but derived from analogue evidence rather than identical structures."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

